const test = require('node:test');
const assert = require('node:assert');
const fs = require('node:fs');
const path = require('node:path');
const os = require('node:os');
const { loadConfig } = require('./config-loader');

function writeTempConfig(content) {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'config-loader-'));
  const filePath = path.join(dir, 'config.json');
  if (content !== undefined) fs.writeFileSync(filePath, content);
  return filePath;
}

test('returns defaults when the file is missing', () => {
  const defaults = { host: 'localhost', port: 3000 };
  const result = loadConfig(path.join(os.tmpdir(), 'config-loader-does-not-exist.json'), defaults);
  assert.deepStrictEqual(result, defaults);
});

test('returns empty object when the file is missing and no defaults given', () => {
  const result = loadConfig(path.join(os.tmpdir(), 'config-loader-does-not-exist.json'));
  assert.deepStrictEqual(result, {});
});

test('merges defaults with user values', () => {
  const filePath = writeTempConfig(JSON.stringify({ port: 8080, debug: true }));
  const result = loadConfig(filePath, { host: 'localhost', port: 3000, retries: 3 });
  assert.deepStrictEqual(result, { host: 'localhost', port: 8080, retries: 3, debug: true });
});

test('preserves user values when they conflict with defaults', () => {
  const filePath = writeTempConfig(JSON.stringify({ host: 'user-host', port: 9000 }));
  const result = loadConfig(filePath, { host: 'default-host', port: 3000 });
  assert.strictEqual(result.host, 'user-host');
  assert.strictEqual(result.port, 9000);
});

test('does not mutate the defaults object', () => {
  const defaults = { host: 'default-host' };
  const filePath = writeTempConfig(JSON.stringify({ host: 'user-host' }));
  loadConfig(filePath, defaults);
  assert.deepStrictEqual(defaults, { host: 'default-host' });
});
